{"sql":"CREATE TABLE IF NOT EXISTS employees.monthly_reports (
  report_id SERIAL PRIMARY KEY,
  report_date DATE NOT NULL,
  department_count INTEGER NOT NULL,
  total_employees INTEGER NOT NULL,
  avg_salary DECIMAL NOT NULL,
  generated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE OR REPLACE PROCEDURE employees.generate_monthly_report(report_date DATE)
LANGUAGE plpgsql
AS $$
DECLARE
  dep_count INTEGER;
  emp_count INTEGER;
  avg_sal DECIMAL;
  new_report_id INTEGER;
BEGIN
  SELECT COUNT(*) INTO dep_count FROM employees.departments;
  SELECT COUNT(*) INTO emp_count FROM employees.employees WHERE current_employee = TRUE;
  SELECT AVG(amount) INTO avg_sal FROM employees.salaries WHERE to_date = '9999-01-01';

  INSERT INTO employees.monthly_reports(report_date, department_count, total_employees, avg_salary)
  VALUES (report_date, dep_count, emp_count, avg_sal)
  RETURNING report_id INTO new_report_id;

  RETURN new_report_id;
END;
$$;"}

{"sql":"CREATE TABLE IF NOT EXISTS employees.salary_alerts (
  alert_id SERIAL PRIMARY KEY,
  employee_id INTEGER NOT NULL,
  salary_amount DECIMAL NOT NULL,
  alert_date TIMESTAMPTZ DEFAULT NOW(),
  status VARCHAR(20) DEFAULT 'new'
);

CREATE OR REPLACE FUNCTION employees.high_salary_alert_fn()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.amount > 120000 THEN
    INSERT INTO employees.salary_alerts(employee_id, salary_amount)
    VALUES (NEW.employee_id, NEW.amount);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS high_salary_alert ON employees.salaries;
CREATE TRIGGER high_salary_alert
AFTER INSERT ON employees.salaries
FOR EACH ROW
EXECUTE FUNCTION employees.high_salary_alert_fn();"}

