{"sql":"CREATE OR REPLACE PROCEDURE employees.generate_monthly_report(report_date DATE, OUT report_generated_id INTEGER)
LANGUAGE plpgsql
AS $$
DECLARE
  dep_count INTEGER;
  emp_count INTEGER;
  avg_sal DECIMAL;
BEGIN
  SELECT COUNT(*) INTO dep_count FROM employees.department;
  SELECT COUNT(*) INTO emp_count FROM employees.employee WHERE id IN (SELECT employee_id FROM employees.department_employee WHERE to_date > CURRENT_DATE);
  SELECT AVG(amount) INTO avg_sal FROM employees.salary WHERE to_date = '9999-01-01';

  INSERT INTO employees.monthly_reports(report_date, department_count, total_employees, avg_salary)
  VALUES (report_date, dep_count, emp_count, avg_sal)
  RETURNING report_id INTO report_generated_id;
END;
$$;"}
